<?php
require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$today=date('Y-m-d');$start=(string)($_GET['mulai']??date('Y-m-01'));$end=(string)($_GET['sampai']??$today);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end=$today;if($start>$end){$tmp=$start;$start=$end;$end=$tmp;}$stmt=mysqli_prepare($conn,"SELECT COUNT(*) jumlah,COALESCE(SUM(total),0) omzet,COALESCE(AVG(total),0) rata FROM pesanan WHERE DATE(dibuat_pada) BETWEEN ? AND ? AND status_pesanan='selesai' AND status_pembayaran='berhasil'");mysqli_stmt_bind_param($stmt,'ss',$start,$end);mysqli_stmt_execute($stmt);$summary=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,"SELECT DATE(dibuat_pada) tanggal,COUNT(*) jumlah,COALESCE(SUM(total),0) omzet FROM pesanan WHERE DATE(dibuat_pada) BETWEEN ? AND ? AND status_pesanan='selesai' AND status_pembayaran='berhasil' GROUP BY DATE(dibuat_pada) ORDER BY tanggal DESC");mysqli_stmt_bind_param($stmt,'ss',$start,$end);mysqli_stmt_execute($stmt);$days=mysqli_stmt_get_result($stmt);$stmt2=mysqli_prepare($conn,"SELECT dp.nama_produk,SUM(dp.jumlah) terjual,SUM(dp.subtotal) omzet FROM detail_pesanan dp JOIN pesanan p ON p.id_pesanan=dp.id_pesanan WHERE DATE(p.dibuat_pada) BETWEEN ? AND ? AND p.status_pesanan='selesai' AND p.status_pembayaran='berhasil' GROUP BY dp.nama_produk ORDER BY terjual DESC LIMIT 10");mysqli_stmt_bind_param($stmt2,'ss',$start,$end);mysqli_stmt_execute($stmt2);$tops=mysqli_stmt_get_result($stmt2);madin_admin_header('Laporan Penjualan','laporan');?><div class="admin-card"><form class="filter-row" method="get"><label>Dari <input type="date" name="mulai" value="<?=madin_e($start)?>"></label><label>Sampai <input type="date" name="sampai" value="<?=madin_e($end)?>"></label><button class="btn">Terapkan</button><a class="btn secondary" href="laporan.php">Bulan ini</a></form><p style="font-size:12px;color:#777">Laporan menghitung pesanan berstatus selesai dan pembayaran berhasil.</p></div><div class="admin-grid"><div class="stat-card"><div class="stat-label">Transaksi selesai</div><div class="stat-value"><?=number_format((int)$summary['jumlah'],0,',','.')?></div></div><div class="stat-card"><div class="stat-label">Omzet bersih tercatat</div><div class="stat-value" style="font-size:22px"><?=madin_money($summary['omzet'])?></div></div><div class="stat-card"><div class="stat-label">Rata-rata transaksi</div><div class="stat-value" style="font-size:22px"><?=madin_money($summary['rata'])?></div></div></div><div class="admin-card"><h2>Penjualan per hari</h2><table class="admin-table"><thead><tr><th>Tanggal</th><th>Jumlah transaksi</th><th>Omzet</th></tr></thead><tbody><?php if($days&&mysqli_num_rows($days)):while($d=mysqli_fetch_assoc($days)):?><tr><td><?=madin_e(date('d/m/Y',strtotime($d['tanggal'])))?></td><td><?=$d['jumlah']?></td><td><?=madin_money($d['omzet'])?></td></tr><?php endwhile;else:?><tr><td colspan="3" class="empty-state">Belum ada penjualan selesai pada periode ini.</td></tr><?php endif;?></tbody></table></div><div class="admin-card"><h2>Produk terlaris</h2><table class="admin-table"><thead><tr><th>Produk</th><th>Jumlah terjual</th><th>Omzet item</th></tr></thead><tbody><?php if($tops&&mysqli_num_rows($tops)):while($t=mysqli_fetch_assoc($tops)):?><tr><td><?=madin_e($t['nama_produk'])?></td><td><?=$t['terjual']?></td><td><?=madin_money($t['omzet'])?></td></tr><?php endwhile;else:?><tr><td colspan="3" class="empty-state">Belum ada data produk terjual.</td></tr><?php endif;?></tbody></table></div><?php mysqli_stmt_close($stmt2);madin_admin_footer();?>
